use super::*;
use crate::money::{money, Money};

/// What the position is worth at a given price, after carry.
pub fn outcome_at(cap: &Capacity, shares: i64, at: Money, carry: &Carry) -> Outcome {
    let cur = cap.equity.currency;
    let gross = shares * (cap.price.minor - at.minor);
    // Borrow accrues on the position's value, day by day. Approximated on the ENTRY value, which is
    // conservative while the trade is winning and optimistic while it is losing — stated rather
    // than modelled precisely, because the exact convention varies by broker.
    let borrow = ((shares * cap.price.minor) as f64 * carry.borrow_apr * carry.days_held as f64 / 365.0).round() as i64;
    let divs = shares * carry.dividends_per_share.minor;
    let net = gross - borrow - divs - carry.commission.minor;
    Outcome {
        at_price: at,
        move_pct: (at.minor - cap.price.minor) as f64 / cap.price.minor as f64,
        gross: money(gross, cur),
        borrow_cost: money(borrow, cur),
        dividends_owed: money(divs, cur),
        commission: carry.commission,
        net: money(net, cur),
        return_on_equity: net as f64 / cap.equity.minor as f64,
        reachable: at.minor < cap.margin_call_price.minor,
    }
}
